extends SceneTree

const Configuration = preload("res://scenes/server/server_configuration.gd")

func _initialize() -> void:
	var configuration: Configuration = Configuration.new()
	if not configuration.load_configuration("/Users/le-evanmcpheron/Documents/Godot/briarwake/fixtures/config/server.valid.json"):
		quit(1)
		return
	if configuration.rules_version.is_empty() or configuration.content_version.is_empty():
		quit(1)
		return
	if configuration.load_configuration("/Users/le-evanmcpheron/Documents/Godot/briarwake/fixtures/config/server.invalid-rate.json"):
		quit(1)
		return
	if not configuration.rules_version.is_empty() or not configuration.content_version.is_empty():
		quit(1)
		return
	print("Passed: failed reload clears validated revision state")
	quit(0)
